PH = []

PH.append(dict(
 id=4, title_en="Detailed structural analysis and design", title_ar="التحليل والتصميم الإنشائي التفصيلي (بلاطات وكمرات وأعمدة وأساسات وسلالم وحوائط ساندة)",
 purpose="Design every structural element to the code, detail the reinforcement and issue drawings, schedules and a calculation report that a checker can follow.",
 inputs=["Phase 3 design basis, layout, loads, materials", "Soil report", "Final architectural dimensions and openings", "MEP penetrations and equipment weights (water tank, AC units, lift)"],
 steps=[
  ("Build the analysis model or the hand-calc scheme: slab panels (support conditions per edge), continuous beams, frames (2D or 3D), foundation model. State assumptions (rigid/elastic supports, cracked section factors).", "M", ["R:model|Structure|Analytical Model|Boundary Conditions","R:model|Structure|Analytical Model|Check"], "R.X can tag boundary conditions (fixed/pinned/roller/free) on columns/foundations but there is NO structural solver (no frame/beam/slab analysis)."),
  ("Slabs: solid slab one-way (long/short >= 2) or two-way; bending moments from code coefficient tables or yield-line/FE; check minimum thickness for deflection; min steel (shrinkage/temperature) and max spacing; cantilevers/balconies design incl. edge beam torsion; shear check (usually no stirrups).", "P", ["calc:flex","p_calc"], "Only the strip/beam flexure+shear sheet `flex` (ACI 318 form, simplified, cylinder f'c). No moment coefficients, no two-way slab, no deflection."),
  ("Beams: flexure (rectangular / T-beam, singly then doubly reinforced), shear + stirrup spacing, torsion for edge/spandrel beams, deflection (span/depth or computed), crack width, support moment at continuity, development of top steel into columns.", "P", ["calc:flex"], "`flex` gives As, As,min, tension-controlled strain, phi*Mn, phi*Vc only. No stirrup design, no T-beam, no torsion/deflection/crack."),
  ("Columns: axial + uniaxial/biaxial moment (interaction diagram), slenderness (braced/unbraced), minimum eccentricity, steel ratio limits (min ~0.8 %, max ~4-6 % - check ECP 203), tie spacing/size, splice zone.", "M", [], "No column design sheet or interaction diagram."),
  ("Foundations: service-load bearing check (q <= allowable, no uplift under combinations), settlement/differential settlement, ultimate design: one-way shear, punching shear at d/2, flexure in both directions, development length of bars, tie beams/strap design; raft: soil springs or rigid method, punching under columns, edge details. Egyptian reference ECP 202 (check clauses).", "P", ["calc:bear","dc_soil","fn:dcBearing","calc:flex"], "`bear` = W/A vs qa for one base; Terzaghi qu from the log. No punching, no one-way shear for footings, no raft, no settlement."),
  ("Stairs: waist slab as one-way inclined slab (span horizontal projection), landings, loads (self weight of steps + finishes + live), reinforcement incl. bent bars at re-entrant corners, support on beams/walls.", "P", ["calc:flex","rv_stair"], "Can run `flex` per metre strip; stair geometry is in R.X."),
  ("Retaining walls / basement walls / ramp walls if the plot has level change: active/at-rest earth pressure + surcharge + water; stability (overturning FS >= ~1.5-2.0, sliding FS >= ~1.5, bearing); stem and base design; drainage and waterproofing.", "M", ["calc:float"], "Only flotation (`float`, for a well) exists - no retaining wall sheet."),
  ("Seismic: ECP 201 zone + site class -> base shear, distribution, drift; check frame detailing class (ductility). Wind on a 2-storey villa rarely governs.", "P", ["env_eq","env_wind"], "Eurocode-8-form spectrum and ASCE 7 base shear (ECP 201's own spectrum/zone table not coded; wind: ECP 201 has its own chapter - the panel says it does not apply it)."),
  ("Serviceability: deflection limit (e.g. span/250 total, span/350-500 after partitions - check ECP 203), crack width (typical 0.3 mm external/0.4 mm internal - check exposure class), vibration for long spans.", "M", [], "Not computed anywhere."),
  ("Detailing: cover, bar spacing, development length ld and lap length (rule of thumb ld ~ 40-50 db for high-yield bars in 25-30 MPa cube concrete, lap = 1.3 ld for ~50 % splice - COMPUTE with the ECP 203 / ACI formula), hooks and bends, stirrup closure at 135 deg, splice location (columns just above slab, beams away from supports), stirrup spacing near supports (confinement zone), curtailment points.", "M", ["R:model|Structure|Reinforcement|Cover","R:model|Structure|Reinforcement|Area","R:model|Structure|Reinforcement|Path"], "Ribbon entries Cover/Area/Path/Fabric Sheet/Couplers are stubs; Rebar entry runs the lift-station rebar viewer (`rb`/`p_rebar`) only."),
  ("Reinforcement schedules / bar bending schedule (BBS): mark, diameter, shape code, cut length, number, total length, weight (kg = d2/162 x m, d in mm). Totals per element and per diameter for ordering.", "P", ["dc_rb","rb","p_rebar"], "dc_rb = rebar take-off tab of document control; `rb` = station rebar. Not generated from R.X columns/beams/slabs."),
  ("Structural drawings: foundation plan + sections, column schedule, beam layout + elevations, slab reinforcement plans per floor, stair detail, general notes (grades, cover, laps, curing), title block.", "P", ["sheet","lb_cx","tab:draft","e_pdf","e_dxf","rv_plancad"], "C.X drawing + sheet composer + title blocks A1-A4. Drawings must be drawn; none auto-produced from a design."),
  ("Calculation report: inputs, load table, results, pass/fail per check, reference clause. Independent check by a second engineer (+ authority stamp).", "P", ["calc:flex","p_review","wf:struct","o_report","dc_rep"], "p_review recomputes the calc sheets and compares with the model; wf_struct is an ordered review (model data > calcs > soil > rebar > seismic > wind > liquefaction > clashes > drawing set)."),
 ],
 outputs=["Calculation report", "Structural drawings: foundation, columns, beams, slabs, stair, details", "Reinforcement schedule / BBS", "Structural quantities (concrete m3, steel kg, formwork m2)", "Authority-approved structural set"],
 checks=[
  "Flexure: Mu <= phi*Mn at every critical section; As >= As,min; As <= As,max (tension-controlled / ductile)",
  "Shear: Vu <= phi*Vn; stirrup spacing <= code max; minimum shear steel where required",
  "Punching (footings, flat slabs): vu <= phi*vc at d/2 from the column face",
  "Deflection: computed or span/depth ratio satisfied; crack width <= limit for the exposure class",
  "Columns: Pu-Mu point inside the interaction diagram; slenderness checked; 0.8 % <= rho <= code max (check ECP 203)",
  "Footing: service q <= allowable (and >= 0 everywhere, i.e. no uplift); differential settlement <= typical L/500 (check the code)",
  "Detailing: cover >= code/exposure; ld and lap provided >= required; bar spacing between min and max",
  "Overall: quantities per m2 BUA in the rule-of-thumb band; two-engineer sign-off"],
 rules=[
  "ECP 203 works with cube strength fcu and gamma_c = 1.5, gamma_s = 1.15 (check the clauses); ACI 318 works with cylinder f'c (rough conversion f'c ~ 0.8 fcu, NEVER use for final design); Eurocode 2 uses fck cylinder. T.O X `flex` is ACI/SBC-style - say so on screen.",
  "RULE OF THUMB steel weight per m3 concrete: footings 60-100, slabs 70-100, beams 130-180, columns 150-250 kg; average 100-130 kg/m3.",
  "RULE OF THUMB min dims: column >= 25x25 cm (check), slab >= 12 cm (roof/floor), beam width >= 20-25 cm, cover 25-30 mm in beams/columns indoors, 50-75 mm against soil.",
  "RULE OF THUMB two-way slab: effective depth d ~ L/35-L/40; simply supported one-way: L/20-L/25 (d); the code table is the authority.",
  "Bar weight kg/m = d^2/162 (d in mm): 10 mm 0.617, 12 mm 0.888, 16 mm 1.58, 18 mm 2.00, 20 mm 2.47, 25 mm 3.85."],
 mistakes=["Designing with unconfirmed loads or an unchecked soil bearing", "Missing top steel at continuous supports and cantilevers", "Stirrups too wide at column/beam joints, 90-degree stirrup hooks", "Forgetting punching at footing and slab-column joints", "Laps all at the same section", "Cover too small against soil -> corrosion", "Copying ACI formulas for an ECP submission"],
 duration="3-6 weeks for a villa (design) + 1 week checks",
 demo="Demo can truthfully show: R.X sizes -> concrete quantities -> `flex` bending check of one slab strip and one beam -> `bear` check of one footing -> rebar weight from dc_rb. It must say 'screening, ACI-form'. Anything more (columns, punching, deflection, ECP 203) is a BUILD item, see gaps 1-3.",
))

PH.append(dict(
 id=5, title_en="MEP design (electrical, HVAC, plumbing, low-current)", title_ar="تصميم الكهروميكانيكا: الكهرباء والتكييف والسباكة والصرف والتيار الخفيف",
 purpose="Design the building services so they fit the architecture and structure, are safe, and can be quantified and priced.",
 inputs=["Architectural plans (rooms, areas, use, glazing, orientation)", "Structural layout (beam depths, shafts, slab openings)", "Utility connection letters (kVA, water pressure, sewer level)", "Owner requirements (AC type, solar heater, smart home, CCTV)"],
 steps=[
  ("ELECTRICAL - Load schedule: every room's lighting (W/m2 or lux method), sockets (typ. 10 A / 16 A), AC units, water heaters, kitchen, pumps, lift, EV charger; connected load, demand/diversity factors, total kVA, phase balance (single/three-phase supply).", "P", ["R:model|Systems|Electrical|Electrical Equipment","R:model|Systems|Electrical|Lighting Fixture","R:model|Systems|Electrical|Device","R:model|Analyze|Reports & Schedules|Panel Schedules","o_sheet"], "R.X placements carry watts; Panel Schedules assign loads to the nearest panel and sum connected watts. No demand/diversity factors, no kVA/phase-balance report."),
  ("Distribution: main distribution board (MDB), sub-boards per floor, circuits (lighting 10 A, sockets 16 A, AC dedicated), RCDs 30 mA on socket/wet circuits, metering point from the utility.", "P", ["R:model|Analyze|Reports & Schedules|Panel Schedules","lib:vxeq"], "Panel schedule only; no single-line diagram tool."),
  ("Cable and breaker sizing: design current Ib = P/(sqrt3 x V x pf) (3-ph) or P/(V x pf) (1-ph); breaker In >= Ib; cable Iz >= In from the code's ampacity table with derating (grouping, temperature, installation); voltage drop <= ~3 % lighting / 5 % total (check local rule); short-circuit check at the board.", "P", ["ace_open","ace_load","env_qc","calc:mot"], "AC unit table: power from cooling and COP, current, breaker from the standard rating series, cable from voltage drop (resistance at conductor temperature). Ampacity tables are NOT typed in: user pastes them. Motor/transformer/voltage-drop calc in env_qc. No lighting/socket circuit sizing, no short-circuit calc."),
  ("Earthing and protection: TN-C-S or TT per utility, earth electrode (rod/plate/foundation earth - often the footing steel is bonded), main equipotential bonding, lightning protection if required, surge protection at MDB.", "M", ["wf:mep"], "wf_mep has a step 'Earthing, lightning, fire, ventilation' that only checks a list; no earthing resistance calc."),
  ("Lighting design: lux target per room (rule of thumb living 100-150, kitchen/desk 300, corridors 100, bath 150-200), lumen method N = E x A / (F x UF x MF), fixture schedule, switching.", "M", ["lib:vxeq"], "No lighting calculation tool."),
  ("HVAC - cooling load room by room (envelope U-values, glass by orientation, people, lights, equipment, ventilation, infiltration), diversity, select unit capacity (split HP / TR) with margin 10 %.", "Y", ["tab:hv","hv_room","hv_import","xf_hv","hv_csv","R:model|Analyze|Energy Analysis|Heating and Cooling Loads"], "V.X hourly design-day estimate (conduction with sol-air, Meinel solar, people, lights, vent, infiltration; no thermal storage = conservative). All inputs editable placeholders."),
  ("Select equipment: split / ducted split / VRF, indoor units per room, outdoor units on roof/balcony with service clearance, refrigerant pipe length limits, condensate drains.", "P", ["lib:vxeq","R:model|Systems|HVAC|Mechanical Equipment","R:model|Systems|HVAC|Air Terminal"], "Equipment library (AHU, FCU, split, VRF, chillers, diffusers) is placeholder data."),
  ("Duct sizing (if ducted): flow per diffuser, equal-friction method, velocity limits, aspect ratio, fittings K values entered by the user, critical-path pressure, fan static.", "Y", ["du_sec","du_load","du_csv","dp_open","dp_flow"], "Darcy-Weisbach + Swamee-Jain, Huebscher rectangular equivalent; duct plan assigns flows downstream and finds the critical path. No fitting tables (user enters K)."),
  ("Fresh air and extract: toilets/kitchen extract (typ. 10-15 ACH bath, kitchen hood), stairwell/garage rules.", "M", [], "No ventilation calc."),
  ("PLUMBING - Water supply: fixture units per fixture, demand (probable flow from fixture units), pipe sizes by velocity (<= 1.5-2.0 m/s) and pressure loss (Hazen-Williams), pressure at highest fixture (>= 1-1.5 bar), ground tank + pump or roof tank (volume = persons x 150-250 L/day x 1-2 days), booster pump selection.", "P", ["calc:hw","calc:mot","env_qc","R:model|Systems|Plumbing & Piping|Plumbing Fixture"], "Hazen-Williams head loss + velocity and pump/motor calc exist. No fixture-unit demand table, no tank-volume or pipe-sizing tool, R.X Pipe/Pipe Sizing are stubs."),
  ("Hot water: solar heater + electric backup, pipe lengths, insulation.", "M", [], ""),
  ("Drainage and vent: fixture units to branch/stack sizes (typ. WC 100 mm, others 50-75 mm), slopes (1-2 %: >= 1:50 for 100 mm, 1:100 for >= 150 mm), vents, manhole at turns/ends (spacing <= 15-25 m), inspection chambers, grease trap for kitchen if required.", "P", ["calc:man","lib:sxpipe","tab:plant"], "Manning full-flow capacity of a gravity pipe; S.X pipe/structure catalogue (placeholder); T.X pipe runs with DN/spec/BOM/iso (not linked to R.X)."),
  ("Sewer or septic: connect to public sewer if invert level allows gravity (check cover and slope), otherwise septic tank + soakaway/cesspit (بيارة) sized by persons x 150-200 L/day x retention 1-2 days; setback from water well / boundary per authority.", "M", [], "No septic/soakaway tool. Networks sample data (sewer/storm/water/fire) exist from the lift-station sample only."),
  ("Rainwater: roof drains (area x rainfall intensity), downpipes, storm connection or soakaway.", "M", [], ""),
  ("Fire fighting: extinguishers per area, civil-defence approval for the building class, hose reel/standpipe if required by class; smoke detectors.", "P", ["lb_cx","wf:mep"], "C.X fire symbols (8); network sample for fire mains exists in sample data."),
  ("LOW-CURRENT - Data/telephone: structured cabling (Cat6) to each room, rack location, wifi AP positions; TV/satellite; intercom/video door phone; CCTV cameras + NVR (storage = cameras x bitrate x days); fire alarm panel + detectors/sounders + battery sizing; access control; smart-home bus if any.", "P", ["lb_cx","lib:cxblk"], "Only CAD symbols in the block library; no riser diagram, no cable schedule, no battery/NVR calc."),
  ("Draw MEP layouts: lighting+socket plans, panel schedule, AC layout + duct, water + drainage plans/risers/isometrics, low-current plans, schedules, specifications.", "P", ["tab:draft","lb_cx","sheet","rv_plancad","plant_sheet"], "CAD + sheets; T.X iso sheet generator for pipes."),
  ("MEP check: wf_mep runs pump, motor, voltage drop, transformer, pipe velocity, safety, earthing in order and says 'missing' where no data.", "Y", ["wf:mep","wf_mep"], "Checks station-type items (pump/transformer) well; building items are mostly missing."),
 ],
 outputs=["Electrical: load schedule, single-line diagram, panel schedules, cable/breaker table, lighting plan, socket plan, earthing detail", "HVAC: cooling-load table, unit schedule, duct drawing + table, drain plan", "Plumbing: fixture-unit table, supply/drain/vent plans, risers, tank & pump data, septic/sewer detail", "Low-current: layouts + riser diagrams + schedules", "MEP specifications + BOQ inputs"],
 checks=["Electrical: Ib <= In <= Iz for every circuit; VD <= limit; earth fault loop / RCD operation; main kVA <= utility approval; every socket circuit RCD-protected", "HVAC: unit capacity >= room load x (1.0-1.15); duct velocity <= limit; total static within fan data; condensate falls", "Plumbing: velocity within 0.6-2.0 m/s; residual pressure >= 1 bar at worst fixture; drain slope >= minimum and flow depth < ~0.7 D; vent for every trap", "Septic/sewer: capacity >= persons x per-capita; levels allow gravity", "Fire: civil-defence approval in file", "All penetrations through slabs and beams are shown on the structural set"],
 rules=["RULE OF THUMB HVAC (Egypt, residential): 120-180 W per m2 conditioned area; 1 TR = 3.517 kW; 1 HP split ~ 9000-12000 Btu/h; ~1 HP per 10-14 m2 in a villa room with average glazing. Load calc supersedes this.", "RULE OF THUMB electrical: villa connected load 80-150 W/m2, after diversity ~ 40-70 W/m2; typical main supply 3-phase 380/220 V 50 Hz, 63-125 A for a villa (utility decides).", "RULE OF THUMB water: 150-250 L/person/day (check local), tank volume 1-2 days; supply pipe velocity 1.0-1.5 m/s.", "RULE OF THUMB drains: 100 mm at 1 % (1:100) minimum for WC branches where allowed (check code), 50 mm basin/shower at 2 %; manholes every <= 15-20 m.", "RULE OF THUMB duct: main 6-8 m/s, branches 3-5 m/s, friction 0.8-1.0 Pa/m (residential 0.6-0.8)."],
 mistakes=["AC outdoor units without airflow clearance", "Condensate drains forgotten", "Sockets without RCD in bathrooms/kitchens", "Panel placed in bathroom/kitchen wall or behind a door", "Septic tank too close to a water well or boundary", "No riser shafts reserved -> pipes through beams", "Cable sized for current only (no voltage drop / derating)"],
 duration="3-6 weeks for all disciplines (parallel to structural design)",
 demo="Good existing coverage for HVAC cooling load > duct > AC electrical. Electrical load schedule/panel and plumbing sizing need small builds to be convincing (gaps 5-7).",
))
